<template>
  <div class="row">
    <span class="dashboard-text-color" style="margin-top: 9px"
      >{{ $t('logs_per_page') }}:
    </span>
    <q-select
      borderless
      dense
      v-model="pagination.page_size"
      :options="pagination_options"
      @update:model-value="updatePageCount"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSystemsLogsStore } from 'src/store/main';

export default defineComponent({
  mixins: [],
  props: {},
  methods: {
    updatePageCount(data: any) {
      console.log(data);
      this.pagination.page_size = data;
      const event = new CustomEvent('update_page_size', {});
      document.dispatchEvent(event);
    },
    validatePaginationSize() {
      if (this.pagination.page_size <= 50) return;
      this.pagination.page_size = 50;
    },
  },
  mounted() {
    this.validatePaginationSize();
  },
  setup() {
    const system_logs_store = useSystemsLogsStore();
    const { pagination } = storeToRefs(system_logs_store);

    return {
      pagination,
      pagination_options: ref(['10', '20', '25', '50']),
    };
  },
});
</script>
<style lang="scss" scoped>
body.body--dark .dashboard-text-color {
  color: #c4c4c4;
}

body.body--light .dashboard-text-color {
  color: #707070;
}
</style>
