  message?: string;
}

export default defineComponent({
  name: 'SystemLogs',
  mixins: [dateUtils, DashboardHelper, helperMixin],
  components: {
    SubHeader,
    ColumnOrderBy,
    PaginationSettings,
    Loader,
  },
  computed: {
    // Computed properties for navigation
    currentLogIndex(): number {
      if (!this.selectedLog || !this.filteredLogs.length) return -1;
      return this.filteredLogs.findIndex(
        (log: { id: any }) => log.id === this.selectedLog?.id,
      );
    },

    canNavigatePrevious(): boolean {
      return this.currentLogIndex > 0;
    },

    canNavigateNext(): boolean {
      return (
        this.currentLogIndex >= 0 &&
        this.currentLogIndex < this.filteredLogs.length - 1
      );
    },
  },
  async mounted() {
    // Load initial data sequentially to prevent Loki rate limiting
    await this.loadAvailableServices();

    // Load logs first, then stats with delay to prevent "too many outstanding requests"
    await this.refreshLogs();

    // Add delay before loading statistics to prevent rate limiting
    setTimeout(async () => {
      await this.refreshLogsStats();
    }, 1000);

    // Load ACE editor script
    if (!(window as any).ace) {
      const script = document.createElement('script');
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/ace/1.4.12/ace.js';
      script.onload = () => {
        nextTick(() => {
          if (this.viewMode === 'raw') {
            this.initializeAceEditor();
          }
        });
      };
      document.head.appendChild(script);
    } else {
      nextTick(() => {
        if (this.viewMode === 'raw') {
          this.initializeAceEditor();
        }
      });
    }
    document.addEventListener(
      'get_sorted_system_logs',
      this.sortAndUpdatedData,
    );
    document.addEventListener('update_page_size', this.refreshLogs);
  },
  unmounted() {
    document.removeEventListener(
      'get_sorted_system_logs',
      this.sortAndUpdatedData,
    );
    document.removeEventListener('update_page_size', this.refreshLogs);
  },
  methods: {
    async setQuickFilter(level: string | null) {
      this.activeQuickFilter = level;

      if (level !== null) {
        const selectedLevel = this.logLevelOptions.find(
          (log) => log.value === level,
        );
        if (selectedLevel) {
          this.filters.logLevel = selectedLevel.label;
        }
      } else {
        //For click on total logs
        this.filters.logLevel = level;
      }

      // Close any expanded row when filtering
      this.selectedLog = null;

      // Reset pagination to first page
      this.pagination.current_page = 1;

      //filters.value.service = level;
      // Apply the filter
      await this.refreshLogs();
    },

    async clearQuickFilter() {
      await this.setQuickFilter(null);
    },

    async loadAvailableServices() {
      try {
        const services = await systemLogsApiService.getAvailableServices();
        // Add null safety check for services response
        if (services && typeof services === 'object') {
          this.serviceOptions = Object.entries(services).map(
            ([label, value]) => ({
              label,
              value,
            }),
          );
        } else {
          console.warn('Invalid services response format:', services);
          throw new Error('Invalid services response');
        }
      } catch (error) {
        console.error('Failed to load available services:', error);
        // Updated fallback services to match Loki service labels
        this.serviceOptions = [
          { label: 'doc2-api', value: 'doc2-api' },
          { label: 'extraction-service', value: 'extraction-service' },
          { label: 'ocr-service', value: 'ocr-service' },
          { label: 'workflow-service', value: 'workflow-service' },
          { label: 'auto-accounting', value: 'auto-accounting' },
          { label: 'import-email', value: 'import-email' },
          { label: 'import-ftp', value: 'import-ftp' },
          { label: 'docflow', value: 'docflow' },
          { label: 'operator', value: 'operator' },
          { label: 'docnet', value: 'docnet' },
        ];
      }
    },

    async loadLogStats() {
      try {
        // Build base Loki query for stats
        let baseQuery = '{service="doc2-api"}';

        // Add service filter if specified
        if (this.filters.service) {
          const serviceValue = this.isOptionObject(this.filters.service)
            ? this.filters.service.value
            : this.filters.service;
          baseQuery = `{service="${serviceValue}"}`;
        }

        // Add search term filter if specified
        if (this.filters.searchTerm) {
          baseQuery += ` |= "${this.filters.searchTerm}"`;
        }

        // Convert dates to ISO format with time
        let startTime = '';
        let endTime = '';

        if (this.filters.fromDate) {
          const startDate = new Date(this.filters.fromDate);
          startDate.setHours(0, 0, 0, 0);
          startTime = startDate.toISOString();
        }
        if (this.filters.toDate) {
          const endDate = new Date(this.filters.toDate);
          endDate.setHours(23, 59, 59, 999);
          endTime = endDate.toISOString();
        }

        // Get org_id using the helper function
        const orgId = getOrgId();
        console.log('🔍 [SystemLogs] Debug Info:', {
          baseQuery,
          startTime,
          endTime,
          orgId,
          filterService: this.filters.service,
          filterLogLevel: this.filters.logLevel,
          filterSearchTerm: this.filters.searchTerm,
        });

        // Use proper Loki count_over_time aggregation with org_id
        const stats = await systemLogsApiService.getLogCounts(
          baseQuery,
          startTime,
          endTime,
          orgId,
        );
        console.log('📊 [SystemLogs] Stats Response:', stats);

        this.logStats = {
          total: stats.total || 0,
          errors: stats.errors || 0,
          warnings: stats.warnings || 0,
          info: stats.info || 0,
          debug: stats.debug || 0,
        };
      } catch (error) {
        console.error('Failed to load log statistics:', error);
        notify.error('Failed to load log statistics');
      }
    },

    isOptionObject(option: any): option is { label: string; value: string } {
      return option && typeof option === 'object' && 'value' in option;
    },

    async loadLogs() {
      try {
        const params = new URLSearchParams();

        // Build Loki query with correct service labels and org_id
        let lokiQuery = '{service="doc2-api"}'; // Default to doc2-api service

        // Add service filter if specified (using correct Loki service label)
        if (this.filters.service) {
          const serviceValue = this.isOptionObject(this.filters.service)
            ? this.filters.service.value
            : this.filters.service;
          lokiQuery = `{service="${serviceValue}"}`;
        }

        // Add org_id to the LogQL query (not as URL parameter)
        const orgId = getOrgId();
        if (orgId) {
          lokiQuery += ` | json | org_id="${orgId}"`;
        }

        console.log('🔍 [LoadLogs] Debug Info:', {
          baseQuery: lokiQuery,
          orgId,
          filterService: this.filters.service,
          filterLogLevel: this.filters.logLevel,
          filterSearchTerm: this.filters.searchTerm,
          fromDate: this.filters.fromDate,
          toDate: this.filters.toDate,
        });

        // Add text-based filtering for log levels and search terms
        const textFilters = [];
        if (this.filters.logLevel) {
          const level = this.isOptionObject(this.filters.logLevel)
            ? this.filters.logLevel.value.toLowerCase()
            : this.filters.logLevel.toLowerCase();

          // Use text filtering instead of level parameter since only "info" level exists
          switch (level) {
            case 'error':
              textFilters.push('|~ "ERROR|Exception|Failed"');
              break;
            case 'warning':
              textFilters.push('|~ "WARN|WARNING"');
              break;
            case 'debug':
              textFilters.push('|~ "DEBUG"');
              break;
            case 'info':
              textFilters.push('|~ "INFO"');
              break;
          }
        }

        if (this.filters.searchTerm) {
          textFilters.push(`|= "${this.filters.searchTerm}"`);
        }

        // Combine query with text filters
        if (textFilters.length > 0) {
          lokiQuery += ' ' + textFilters.join(' ');
        }

        params.append('query', lokiQuery);

        // Convert dates to ISO format with time
        if (this.filters.fromDate) {
          const startDate = new Date(this.filters.fromDate);
          startDate.setHours(0, 0, 0, 0);
          params.append('start', startDate.toISOString());
        }
        if (this.filters.toDate) {
          const endDate = new Date(this.filters.toDate);
          endDate.setHours(23, 59, 59, 999);
          params.append('end', endDate.toISOString());
        }

        // Fix pagination NaN issue - ensure valid numbers
        const pageSize = this.pagination?.page_size || 50;
        const currentPage = this.pagination?.current_page || 1;
        const limit = Math.min(pageSize, 1000); // Cap at 1000 to prevent overload

        params.append('limit', limit.toString());

        // Add offset for pagination
        const offset = (currentPage - 1) * pageSize;
        if (offset > 0) {
          params.append('offset', offset.toString());
        }

        console.log('🌐 [LoadLogs] API Call Parameters:', {
          endpoint: 'query_range',
          query: lokiQuery,
          start: params.get('start'),
          end: params.get('end'),
          limit: params.get('limit'),
          offset: params.get('offset'),
        });

        const response = await systemLogsApiService.getLogs(params);

        console.log('📡 [LoadLogs] Raw API Response:', response);
        console.log('📊 [LoadLogs] Response Type:', typeof response);
        console.log(
          '🔍 [LoadLogs] Response Keys:',
          response ? Object.keys(response) : 'null/undefined',
        );

        // Handle Loki response format: response.data.result (not response.logs)
        const lokiResult = response?.data?.result || [];
        console.log('🔍 [LoadLogs] Loki Result Structure:', lokiResult);

        // Transform Loki streams format to log entries format
        const logs: any[] = [];
        let totalEntries = 0;

        lokiResult.forEach((stream: any) => {
          const streamLabels = stream.stream || {};
          const values = stream.values || [];

          console.log('📊 [LoadLogs] Processing stream:', {
            labels: streamLabels,
            valuesCount: values.length,
          });

          values.forEach(([timestampNs, message]: [string, string]) => {
            totalEntries++;
            // Convert nanosecond timestamp to milliseconds
            const timestamp = new Date(parseInt(timestampNs) / 1000000);

            // Extract log level from message (fallback to INFO)
            let level = 'INFO';
            if (/ERROR|Exception|Failed/i.test(message)) {
              level = 'ERROR';
            } else if (/WARN|WARNING/i.test(message)) {
              level = 'WARN';
            } else if (/DEBUG/i.test(message)) {
              level = 'DEBUG';
            }

            logs.push({
              id: `${timestampNs}-${totalEntries}`, // Unique ID
              timestamp: timestamp.toISOString(),
              level: level,
              logger_name: streamLabels.service || 'UNKNOWN',
              message: message,
              org_id: streamLabels.org_id || '',
            });
          });
        });

        console.log('📋 [LoadLogs] Transformed Data:', {
          originalLokiResult: lokiResult.length,
          transformedLogs: logs.length,
          totalEntries: totalEntries,
          sampleLog: logs[0],
        });

        this.logs = logs;
        this.filteredLogs = logs;
        this.total_data = totalEntries;
        this.pagination.total_pages = Math.ceil(
          totalEntries / (this.pagination.page_size || 50),
        );

        // Update raw logs content with null safety
        this.rawLogsContent = logs
          .map(
            (log: {
              timestamp: string | number | Date | undefined;
              level: string;
              logger_name: any;
              message: any;
            }) =>
              `[${date.formatDate(log.timestamp, 'YYYY-MM-DD HH:mm:ss')}]  ${log.level?.toUpperCase().padEnd(7) || 'UNKNOWN'} [${log.logger_name || 'UNKNOWN'}] ${log.message || ''}`,
          )
          .join('\n');

        // Update ACE editor if in raw view
        if (this.viewMode === 'raw' && this.aceEditorInstance) {
          this.aceEditorInstance.setValue(this.rawLogsContent, -1);
        }
      } catch (error) {
        console.error('Failed to load logs:', error);
        notify.error('Failed to load system logs');
      }
    },

    async refreshLogsAndStats() {
      await this.refreshLogs();
      await this.refreshLogsStats();
    },

    async refreshLogs() {
      this.showLoading();
      try {
        await Promise.all([this.loadLogs()]);
      } finally {
        this.hideLoading();
      }
    },

    async refreshLogsStats() {
      this.showLoading();
      try {
        await Promise.all([this.loadLogStats()]);
      } finally {
        this.hideLoading();
      }
    },

    async applyFilters() {
      // Reset pagination to first page when applying filters
      this.pagination.current_page = 1;
      await this.refreshLogs();
      await this.refreshLogsStats();
    },

    getLogLevelColor(level: string) {
      switch (level.toUpperCase()) {
        case 'ERROR':
          return 'red';
        case 'WARN':
          return 'orange';
        case 'WARNING':
          return 'orange';
        case 'INFO':
          return 'blue';
        case 'DEBUG':
          return 'grey';
        default:
          return 'grey';
      }
    },

    getLogLevelTextColor(level: string) {
      switch (level.toUpperCase()) {
        case 'ERROR':
          return 'white';
        case 'WARN':
          return 'white';
        case 'WARNING':
          return 'white';
        case 'INFO':
          return 'white';
        case 'DEBUG':
          return 'white';
        default:
          return 'white';
      }
    },

    async exportLogs() {
      try {
        this.showLoading();

        // Get all logs and create a blob
        const params = new URLSearchParams();

        // Build Loki query with correct service labels for export
        let lokiQuery = '{service="doc2-api"}';

        if (this.filters.service) {
          const serviceValue = this.isOptionObject(this.filters.service)
            ? this.filters.service.value
            : this.filters.service;
          lokiQuery = `{service="${serviceValue}"}`;
        }

        // Add text-based filtering for log levels and search terms
        const textFilters = [];
        if (this.filters.logLevel) {
          const level = this.isOptionObject(this.filters.logLevel)
            ? this.filters.logLevel.value.toLowerCase()
            : this.filters.logLevel.toLowerCase();

          switch (level) {
            case 'error':
              textFilters.push('|~ "ERROR|Exception|Failed"');
              break;
            case 'warning':
              textFilters.push('|~ "WARN|WARNING"');
              break;
            case 'debug':
              textFilters.push('|~ "DEBUG"');
              break;
            case 'info':
              textFilters.push('|~ "INFO"');
              break;
          }
        }

        if (this.filters.searchTerm) {
          textFilters.push(`|= "${this.filters.searchTerm}"`);
        }

        if (textFilters.length > 0) {
          lokiQuery += ' ' + textFilters.join(' ');
        }

        params.append('query', lokiQuery);

        // Convert dates to ISO format with time
        if (this.filters.fromDate) {
          const startDate = new Date(this.filters.fromDate);
          startDate.setHours(0, 0, 0, 0);
          params.append('start', startDate.toISOString());
        }
        if (this.filters.toDate) {
          const endDate = new Date(this.filters.toDate);
          endDate.setHours(23, 59, 59, 999);
          params.append('end', endDate.toISOString());
        }

        // Set higher limit for export
        params.append('limit', '10000');

        const response = await systemLogsApiService.exportLogs(params);

        // Add null safety checks for export response
        const exportLogs = response?.logs || [];

        const logText = exportLogs
          .map(
            (log: {
              timestamp: any;
              created_at: any;
              level: string;
              logger_name: any;
              message: any;
            }) => {
              // Use timestamp if available, otherwise fallback to created_at
              const timestamp = log.timestamp || log.created_at || '';
              // Format timestamp to readable format
              const formattedTimestamp = timestamp
                ? new Date(timestamp)
                    .toLocaleString('en-US', {
                      year: 'numeric',
                      month: '2-digit',
                      day: '2-digit',
                      hour: '2-digit',
                      minute: '2-digit',
                      second: '2-digit',
                      hour12: false,
                    })
                    .replace(',', '')
                : 'NO_TIMESTAMP';
              return `[${formattedTimestamp}] ${(log.level || 'UNKNOWN').toUpperCase().padEnd(7)} [${log.logger_name || 'UNKNOWN'}] ${log.message || ''}`;
            },
          )
          .join('\n');

        const blob = new Blob([logText], { type: 'text/plain' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `system-logs-${date.formatDate(new Date(), 'YYYY-MM-DD-HHmmss')}.txt`;
        a.click();
        window.URL.revokeObjectURL(url);

        notify.success('Logs exported successfully');
      } catch (error) {
        console.error('Failed to export logs:', error);
        notify.error('Failed to export logs');
      } finally {
        this.hideLoading();
      }
    },

    onRowClick(evt: Event, row: LogEntry) {
      // Toggle selection - if clicking the same row, deselect it
      if (this.selectedLog && this.selectedLog.id === row.id) {
        this.selectedLog = null;
      } else {
        this.selectedLog = row;
      }
    },

    navigateToLog(direction: 'previous' | 'next') {
      const currentIndex = this.currentLogIndex;
      if (currentIndex === -1) return;

      let newIndex: number;
      if (direction === 'previous' && this.canNavigatePrevious) {
        newIndex = currentIndex - 1;
      } else if (direction === 'next' && this.canNavigateNext) {
        newIndex = currentIndex + 1;
      } else {
        return;
      }

      this.selectedLog = this.filteredLogs[newIndex];
    },

    closeExpandedRow() {
      this.selectedLog = null;
    },

    async initializeAceEditor() {
      if (this.viewMode === 'raw' && this.$refs.aceEditor) {
        // Load ACE editor dynamically
        try {
          // In a real app, you'd load ace from CDN or npm package
          const ace = (window as any).ace;
          if (ace) {
            this.aceEditorInstance = ace.edit(this.$refs.aceEditor);
            this.aceEditorInstance.setTheme('ace/theme/github');
            this.aceEditorInstance.session.setMode('ace/mode/text');
            this.aceEditorInstance.setValue(this.rawLogsContent, -1);
            this.aceEditorInstance.setOptions({
              readOnly: true,
              fontSize: 12,
              wrap: true,
              showPrintMargin: false,
            });
          }
        } catch (error) {
          console.warn('ACE Editor not available, using fallback textarea');
        }
      }
    },

    async clearFilters() {
      this.filters.fromDate = date.formatDate(
        date.subtractFromDate(new Date(), { days: 7 }),
        'YYYY-MM-DD',
      );
      this.filters.toDate = date.formatDate(new Date(), 'YYYY-MM-DD');
      this.filters.logLevel = null;
      this.filters.service = null;
      this.filters.searchTerm = null;
      await this.refreshLogsAndStats();
    },

    sortAndUpdatedData(params: any) {
      this.filteredLogs = this.filteredLogs.sort(
        (a: { [x: string]: any }, b: { [x: string]: any }) => {
          const aVal = a[params.detail.field];
          const bVal = b[params.detail.field];

          if (aVal == null) return params.detail.direction === 'asc' ? -1 : 1;
          if (bVal == null) return params.detail.direction === 'asc' ? 1 : -1;

          if (typeof aVal === 'number' && typeof bVal === 'number') {
            return params.detail.direction === 'asc'
              ? aVal - bVal
              : bVal - aVal;
          }

          return params.detail.direction === 'asc'
            ? String(aVal).localeCompare(String(bVal))
            : String(bVal).localeCompare(String(aVal));
        },
      );
    },
    // Watch for view mode changes
    watchViewMode() {
      nextTick(() => {
        if (this.viewMode === 'raw') {
          this.initializeAceEditor();
        }
      });
    },
  },
  data() {
    return {
      activeTab: ref('logs'), // Default to logs tab to show current functionality
      viewMode: ref('table'),
      cacheHitRate: ref(94), // Demo data for cache performance knob
      timeInterval: ref('1min'), // Demo data for time interval selector
      logLevel: ref('ERROR'), // Demo data for log level filter
      monitoringMode: ref('auto'), // Demo data for monitoring mode toggle
      updateInterval: ref(1), // Demo data for update interval slider
      aceEditor: ref(null),
      aceEditorInstance: ref(null as any),
      selectedLog: null as LogEntry | null,
      filteredLogs: [] as LogEntry[],
      activeQuickFilter: null as string | null,

      // Filters
      filters: ref({
        fromDate: date.formatDate(
          date.subtractFromDate(new Date(), { days: 7 }),
          'YYYY-MM-DD',
        ),
        toDate: date.formatDate(new Date(), 'YYYY-MM-DD'),
        logLevel: null as string | null,
        service: null as string | null,
        searchTerm: null as string | null,
      }),

      // Options for dropdowns
      logLevelOptions: ref([
        { label: 'ERROR', value: 'error' },
        { label: 'WARNING', value: 'warning' },
        { label: 'INFO', value: 'info' },
        { label: 'DEBUG', value: 'debug' },
      ]),

      serviceOptions: ref<{ label: string; value: string }[]>([]),

      // Log statistics
      logStats: ref<LogStats>({
        total: 0,
        errors: 0,
        warnings: 0,
        info: 0,
        debug: 0,
      }),

      // Table configuration
      logColumns: ref([
        {
          name: 'timestamp',
          label: 'timestamp',
          field: 'timestamp',
          align: 'left',
          sortable: true,
        },
        {
          name: 'level',
          label: 'log_level',
          field: 'level',
          align: 'center',
          sortable: true,
        },
        {
          name: 'logger_name',
          label: 'service',
          field: 'logger_name',
          align: 'left',
          sortable: true,
        },
        {
          name: 'message',
          label: 'message',
          field: 'message',
          align: 'left',
          sortable: false,
        },
      ]),

      logs: [] as LogEntry[],
      // Raw logs for ACE editor
      rawLogsContent: ref(''),
    };
  },
  setup() {
    const systems_logs_store = useSystemsLogsStore();
    const {
      pagination,
      pagination_size_key,
      paginationCount,
      total_data,
      order_by,
    } = storeToRefs(systems_logs_store);

    return {
      pagination,
      pagination_size_key,
      paginationCount,
      total_data,
      order_by,
    };
  },
  watch: {
    viewMode() {
      this.watchViewMode();
    },
    // Sync quick filter with dropdown filter
    'filters.logLevel'(newVal) {
      this.activeQuickFilter = newVal;
    },
  },
});
</script>

